UPDATE `tokens` SET `art_asset` = CASE `art_asset` WHEN '/assets/tokens/creatures/cave-bat-01.png' THEN '/creature-assets/tokens/creatures/cave-bat-01.png' WHEN '/assets/tokens/creatures/imp-01.png' THEN '/creature-assets/tokens/creatures/imp-01.png' WHEN '/assets/tokens/creatures/giant-rat-01.png' THEN '/creature-assets/tokens/creatures/giant-rat-01.png' WHEN '/assets/tokens/creatures/goblin-raider-01.png' THEN '/creature-assets/tokens/creatures/goblin-raider-01.png' WHEN '/assets/tokens/creatures/gray-wolf-01.png' THEN '/creature-assets/tokens/creatures/gray-wolf-01.png' WHEN '/assets/tokens/creatures/skeleton-guard-01.png' THEN '/creature-assets/tokens/creatures/skeleton-guard-01.png' WHEN '/assets/tokens/creatures/shambling-zombie-01.png' THEN '/creature-assets/tokens/creatures/shambling-zombie-01.png' WHEN '/assets/tokens/creatures/black-bear-01.png' THEN '/creature-assets/tokens/creatures/black-bear-01.png' WHEN '/assets/tokens/creatures/mimic-chest-01.png' THEN '/creature-assets/tokens/creatures/mimic-chest-01.png' WHEN '/assets/tokens/creatures/dire-wolf-01.png' THEN '/creature-assets/tokens/creatures/dire-wolf-01.png' WHEN '/assets/tokens/creatures/giant-cave-spider-01.png' THEN '/creature-assets/tokens/creatures/giant-cave-spider-01.png' WHEN '/assets/tokens/creatures/ogre-brute-01.png' THEN '/creature-assets/tokens/creatures/ogre-brute-01.png' WHEN '/assets/tokens/creatures/owlbear-01.png' THEN '/creature-assets/tokens/creatures/owlbear-01.png' WHEN '/assets/tokens/monsters/shadow-dire-warg-01.png' THEN '/creature-assets/tokens/monsters/shadow-dire-warg-01.png' WHEN '/assets/tokens/monsters/hungry-01.png' THEN '/creature-assets/tokens/monsters/hungry-01.png' WHEN '/assets/tokens/monsters/young-green-dragon-01.png' THEN '/creature-assets/tokens/monsters/young-green-dragon-01.png' WHEN '/assets/tokens/creatures/ancient-treant-01.png' THEN '/creature-assets/tokens/creatures/ancient-treant-01.png' ELSE `art_asset` END WHERE `art_asset` IN ('/assets/tokens/creatures/cave-bat-01.png', '/assets/tokens/creatures/imp-01.png', '/assets/tokens/creatures/giant-rat-01.png', '/assets/tokens/creatures/goblin-raider-01.png', '/assets/tokens/creatures/gray-wolf-01.png', '/assets/tokens/creatures/skeleton-guard-01.png', '/assets/tokens/creatures/shambling-zombie-01.png', '/assets/tokens/creatures/black-bear-01.png', '/assets/tokens/creatures/mimic-chest-01.png', '/assets/tokens/creatures/dire-wolf-01.png', '/assets/tokens/creatures/giant-cave-spider-01.png', '/assets/tokens/creatures/ogre-brute-01.png', '/assets/tokens/creatures/owlbear-01.png', '/assets/tokens/monsters/shadow-dire-warg-01.png', '/assets/tokens/monsters/hungry-01.png', '/assets/tokens/monsters/young-green-dragon-01.png', '/assets/tokens/creatures/ancient-treant-01.png');--> statement-breakpoint
UPDATE `tokens` SET `hp` = (SELECT `default_hp` FROM `creature_catalog` WHERE `token_asset` = `tokens`.`art_asset` AND `is_active` = 1 LIMIT 1), `max_hp` = (SELECT `default_hp` FROM `creature_catalog` WHERE `token_asset` = `tokens`.`art_asset` AND `is_active` = 1 LIMIT 1), `updated_at` = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE `kind` = 'monster' AND `hp` IS NULL AND `max_hp` IS NULL AND EXISTS (SELECT 1 FROM `creature_catalog` WHERE `token_asset` = `tokens`.`art_asset` AND `is_active` = 1);--> statement-breakpoint
UPDATE `encounters` SET `map_package_json` = '{"format":"dnd-battle-map","version":1,"id":"grandfather-tree-roots-v1","name":"Grandfather Tree Roots","description":"The shaded base of the Grandfather Tree, where an immense curved trunk wall and branching, overlapping roots shape the entire battlefield.","biome":"forest","mood":"daylight","seed":"GRANDFATHER-TREE-ROOTS-V1","width":24,"height":16,"walls":[],"portals":[],"labels":[],"notes":[],"fog":{"mode":"off","sharedPolygon":[{"x":0,"y":0},{"x":12,"y":0},{"x":24,"y":0},{"x":24,"y":8},{"x":24,"y":16},{"x":12,"y":16},{"x":0,"y":16},{"x":0,"y":8}],"walls":[],"doors":[],"circles":[]},"visual":{"kind":"generated-scene","assetUrl":"/map-assets/grandfather-tree-roots-01.jpg","pixelWidth":3072,"pixelHeight":2048},"source":{"kind":"generated-scene"},"createdAt":0}', `active_map_preset_id` = NULL, `map_asset` = '', `grid_width` = 24, `grid_height` = 16, `version` = `version` + 1, `updated_at` = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE `map_package_json` IS NULL OR instr(`map_package_json`, '"visual"') = 0;--> statement-breakpoint
DELETE FROM `map_presets` WHERE instr(`package_json`, '"visual"') = 0;--> statement-breakpoint
UPDATE `encounters` SET `map_package_json` = json_remove(json_remove(`map_package_json`, '$.sceneObjects'), '$.visual.sceneKitId'), `version` = `version` + 1, `updated_at` = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE `map_package_json` IS NOT NULL AND json_valid(`map_package_json`) = 1 AND (json_type(`map_package_json`, '$.sceneObjects') IS NOT NULL OR json_type(`map_package_json`, '$.visual.sceneKitId') IS NOT NULL);--> statement-breakpoint
UPDATE `map_presets` SET `package_json` = json_remove(json_remove(`package_json`, '$.sceneObjects'), '$.visual.sceneKitId') WHERE json_valid(`package_json`) = 1 AND (json_type(`package_json`, '$.sceneObjects') IS NOT NULL OR json_type(`package_json`, '$.visual.sceneKitId') IS NOT NULL);--> statement-breakpoint
